(()=>{
 const list=document.getElementById('vault-accounts');if(!list)return;
 const providers=[['gmail','Gmail'],['linkedin','LinkedIn'],['indeed','Indeed'],['dice','Dice'],['career_portals','Career Portals']];
 async function request(options){const response=await fetch('/api/auto-apply/vault',{cache:'no-store',...options});const data=await response.json();if(!response.ok)throw Error(data.error||'Vault request failed.');return data;}
 for(const [provider,label] of providers){
 const row=document.createElement('details');row.className='vault-account';const summary=document.createElement('summary');const logo=document.createElement('span');logo.className='vault-logo';logo.innerHTML=provider==='career_portals'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M7 7.5h.01M10 7.5h.01M8 14h8M8 17h5"/></svg>':providerLogo(provider);const title=document.createElement('strong');title.textContent=label;const status=document.createElement('small');status.textContent='Not saved';summary.append(logo,title,status);row.append(summary);
 const form=document.createElement('form');form.className='vault-form';const username=document.createElement('input');username.type=['gmail','career_portals'].includes(provider)?'email':'text';username.autocomplete='username';username.maxLength=254;username.required=true;const usernameLabel=document.createElement('label');usernameLabel.textContent=provider==='career_portals'?'Default application email':'Email or username';usernameLabel.append(username);
 const password=document.createElement('input');password.type='password';password.autocomplete='current-password';password.maxLength=2048;const passwordLabel=document.createElement('label');passwordLabel.textContent=provider==='career_portals'?'Default portal password':'Password';const shell=document.createElement('div');shell.className='vault-password';const eye=document.createElement('button');eye.type='button';eye.setAttribute('aria-label','Show password');eye.setAttribute('aria-pressed','false');eye.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 12s4-6 10-6 10 6 10 6-4 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>';eye.onclick=()=>{const visible=password.type==='password';password.type=visible?'text':'password';eye.setAttribute('aria-label',visible?'Hide password':'Show password');eye.setAttribute('aria-pressed',String(visible));};shell.append(password,eye);passwordLabel.append(shell);
 const controls=document.createElement('div');controls.className='vault-controls';const save=document.createElement('button');save.type='submit';save.className='primary';save.textContent='Save';const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.hidden=true;const notice=document.createElement('p');notice.setAttribute('role','status');controls.append(save,remove);form.append(usernameLabel,passwordLabel,controls,notice);if(provider==='career_portals'){const hint=document.createElement('p');hint.className='form-hint';hint.textContent='Default credentials for employer career portals. Existing accounts may require a different password; verification steps will need your input.';form.prepend(hint);}row.append(form);list.append(row);
 form.onsubmit=async event=>{event.preventDefault();save.disabled=true;notice.textContent='Saving…';try{await request({method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,account:username.value,password:password.value})});password.value='';password.placeholder='Saved securely — leave blank to keep';status.textContent='Saved';remove.hidden=false;notice.textContent='Saved securely.';}catch(error){notice.textContent=error.message;}finally{save.disabled=false;}};
 remove.onclick=async()=>{if(!confirm('Remove saved '+label+' credentials?'))return;remove.disabled=true;try{await request({method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider})});form.reset();password.placeholder='';status.textContent='Not saved';remove.hidden=true;notice.textContent='Credentials removed.';}catch(error){notice.textContent=error.message;}finally{remove.disabled=false;}};
 row.load=async()=>{try{const data=await request();const saved=data.items.find(item=>item.provider===provider);const existing=providerAccount(provider).account;username.value=saved?.account||existing||'';if(saved){status.textContent='Saved';remove.hidden=false;password.placeholder='Saved securely — leave blank to keep';}}catch(error){notice.textContent=error.message;}};
 }
 let loaded=false;document.querySelector('[data-panel="vault"]').addEventListener('click',()=>{if(!loaded){loaded=true;for(const row of list.children)row.load();}});
})();
